import React from 'react';
import {TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {getPermissionLabelById} from '../../helper';
import {useTranslation} from 'react-i18next';
import {IExternalShared} from '../../../../../../../model/interface/envelope.interface';
import TextCM from '../../../../../../../components/Text';
import {DateUtils} from '../../../../../../../utils';
import {IconBluePen, IcRedTrash} from '../../../../../../../assets/images';

type Props = {
  data: IExternalShared;
  onPressEdit?: (data: IExternalShared) => void;
  onPressDelete?: (data: IExternalShared) => void;
};

const ShareItem = ({data, onPressEdit, onPressDelete}: Props) => {
  const {t} = useTranslation();

  const handleOnpressEdit = () => {
    if (onPressEdit) {
      onPressEdit(data);
    }
  };

  const handleOnpressDelete = () => {
    if (onPressDelete) {
      onPressDelete(data);
    }
  };

  return (
    <View style={styles.ctnMain}>
      <TextCM style={styles.txtLabel}>{data.personal}</TextCM>
      <View style={styles.rowItem}>
        <TextCM style={styles.txtTextField}>
          {t('DC.ShareDocument.allowPermission')}
        </TextCM>
        <TextCM style={styles.txtTextValue}>
          {getPermissionLabelById(data.perm)}
        </TextCM>
      </View>
      <View style={styles.rowItem}>
        <TextCM style={styles.txtTextField}>
          {t('DC.ShareDocument.effectFrom')}
        </TextCM>
        <TextCM style={styles.txtTextValue}>
          {DateUtils.convertDateToDDMMYYYY(data.fromDate)}
        </TextCM>
      </View>
      <View style={styles.rowItem}>
        <TextCM style={styles.txtTextField}>
          {t('DC.ShareDocument.effectTo')}
        </TextCM>
        <TextCM style={styles.txtTextValue}>
          {DateUtils.convertDateToDDMMYYYY(data.toDate)}
        </TextCM>
      </View>
      <View style={styles.seperateView} />
      <View style={styles.ctnAction}>
        <TouchableOpacity style={styles.squareIcon} onPress={handleOnpressEdit}>
          <IconBluePen width={16} height={16} />
        </TouchableOpacity>
        <TouchableOpacity
          onPress={handleOnpressDelete}
          style={[styles.squareIcon, {backgroundColor: '#FEECEB'}]}>
          <IcRedTrash width={16} height={16} />
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default ShareItem;
